  const time = p.startedAt > 0 ? fmtClock((p.endedAt ?? d.now) - p.startedAt) : '—'
  const name = `‹ ${shorten(p.type.toLowerCase(), 24)}`
  const words = wrapLines(p.lastText, W - 3, 2)
