      blank(els),
      <Text wrap="truncate">
        {words[0] ? <Text color={C.dim}>{' » '}</Text> : ' '}
        {words[0] ? (
          <Text color={C.muted} italic>
            {words[0]}
          </Text>
        ) : null}
      </Text>,
      <Text color={C.muted} italic wrap="truncate">
        {words[1] ? `   ${words[1]}` : ' '}
      </Text>,
