}

/** The longest head of `s` that fits in `n` cells. */
const head = (s: string, n: number) => {
  let out = ''
  let w = 0
  for (const ch of s) {
    const cw = cellWidth(ch.codePointAt(0) ?? 0)
    if (w + cw > n) break
    out += ch
    w += cw
  }
  return out
}

